import { ChevronRight } from "lucide-react";

const SettingCard = ({
  icon,
  title,
  subtitle,
  onClick,
}) => {
  return (
    <button
      onClick={onClick}
      className="
      w-full
      bg-white
      border
      rounded-xl
      p-5
      flex
      justify-between
      items-center
      hover:shadow-md
      transition
      "
    >
      <div className="flex items-center gap-4">

        <div className="text-blue-600">
          {icon}
        </div>

        <div className="text-left">
          <h2 className="font-semibold">
            {title}
          </h2>

          <p className="text-gray-500 text-sm">
            {subtitle}
          </p>
        </div>

      </div>

      <ChevronRight />

    </button>
  );
};

export default SettingCard;
